-- Run after schema.sql. Safe to rerun: an existing Circulatory: Week 3 is left intact.
with created_week as (
  insert into "POTWWeek" ("topic", "description", "published", "createdById")
  select 'Circulatory System', 'Circulatory system practice questions', true,
    (select "id" from "User" where "username" = '2028efeldman' limit 1)
  where not exists (select 1 from "POTWWeek" where "topic" = 'Circulatory: Week 3')
  returning "id"
)
insert into "POTWProblem" ("weekId", "prompt", "choices", "correctIndex", "imageUrl", "orderIndex")
select created_week."id", questions.prompt, questions.choices::jsonb, questions.correct_index, questions.image_url, questions.order_index
from created_week
cross join (values
  (0, 'Which of the following is an advantage of an open circulatory system?', '["Faster overall metabolic rate and sustained high activity", "Less energy is needed for the system to operate", "Higher hydrostatic pressure for rapid oxygen delivery", "Precise regulation of blood flow to specific organs"]', 1, null),
  (1, 'Suppose a mammal is born with a hole in the septum between its ventricles. Which of the following is not a symptom or consequence for the blood going to its body?', '["Deoxygenated and oxygenated blood may partially mix", "Shortness of breath", "The heart has to pump harder to deliver enough oxygen to the body", "The blood traveling to the rest of the body carries an abnormally high concentration of oxygen"]', 3, null),
  (2, 'Smooth muscle cells can be found in each of the following except:', '["Arteries", "Arterioles", "Capillaries", "Veins"]', 2, null),
  (3, 'In which of the following is the basal lamina (along with the endothelium) the main structural layer of the vessel wall?', '["Capillaries", "Veins", "Arteries", "Arterioles"]', 0, null),
  (4, 'Yanling stands still for several hours and suddenly faints. What can explain the fainting?', '["Blood vessels in the legs constrict, reducing blood flow back to the heart and causing blood pressure to drop", "Contracting leg muscles normally squeeze the veins; without this skeletal muscle pump for a long time, gravity causes blood to pool in her lower legs and blood pressure drops", "The heart rate decreases because the heart muscle becomes fatigued from pumping blood continuously for several hours", "Blood pools in the lungs due to gravity, reducing the amount of oxygen delivered to the brain"]', 1, null),
  (5, 'In the capillaries, blood pressure is 120 mm Hg while osmotic pressure is 110 mm Hg. At this point, what would you expect to happen?', '["Fluid is pulled into the capillary since net filtration pressure is positive", "Fluid is pushed out of the capillary since net filtration pressure is positive", "Fluid is pushed out of the capillary since net filtration pressure is negative", "Fluid is pulled into the capillary since net filtration pressure is negative"]', 1, null),
  (6, 'Yenna''s liver stops producing albumin. Which is the best explanation for what will happen to her tissues?', '["Albumin normally exerts osmotic pressure that pulls fluid into the blood vessels. Fluid will leak out of the capillaries if her liver stops producing it.", "Albumin normally exerts osmotic pressure that pushes fluid out of the blood vessels. Fluid will leak into the capillaries if her liver stops producing it.", "Albumin normally helps red blood cells carry oxygen to tissues. Without albumin, tissues will become swollen due to reduced oxygen delivery.", "Albumin normally prevents fluid from entering the lymphatic vessels. Without albumin, excess fluid will accumulate in the lymphatic system and reduce blood volume."]', 0, null),
  (7, 'Which of the following would you expect to be the thickest?', '["Right atrium", "Right ventricle", "Left atrium", "Left ventricle"]', 3, null),
  (8, 'What is the flow of blood in the human circulatory system?', '["RA → RV → lungs → body → LA → LV", "LA → LV → lungs → RA → RV → body", "RA → RV → lungs → LA → LV → body", "lungs → LA → LV → RA → RV → body"]', 2, null),
  (9, 'Where would you expect the velocity of blood to be the lowest?', '["Left ventricle", "Capillaries", "Right ventricle", "Right atrium"]', 1, null),
  (10, 'Ariana has a diastolic pressure of 40 mm Hg and a systolic pressure of 60 mm Hg. What is her pulse pressure?', '["100 mm Hg", "50 mm Hg", "20 mm Hg", "1.5 mm Hg"]', 2, null),
  (11, 'Oh no! Eli''s AV node is damaged and no longer delays the signal. What would you predict to happen?', '["The heart rate will increase dramatically because the electrical signal travels faster to the ventricles", "Stroke volume will increase since there is no delay", "The ventricles will fail to contract entirely because the signal cannot pass through the bundle of His", "Stroke volume will decrease since the atria and ventricles will contract at the same time, so the atria squeeze against closed valves"]', 3, null),
  (12, 'Jessy takes warfarin, which blocks vitamin K. What would you expect this to do?', '["Vitamin K is necessary to make many clotting factors, so fewer of these will be produced", "Vitamin K is necessary for producing red blood cells, so blocking it will reduce oxygen delivery to tissues", "Vitamin K is necessary for activating platelets, so blocking it will prevent platelets from sticking together at damaged blood vessels", "Vitamin K is necessary for breaking down blood clots, so blocking it will cause clots to accumulate throughout the circulatory system"]', 0, null),
  (13, 'Yanling has a very high HDL to LDL ratio. What can she expect to happen?', '["HDL will get into damaged arterial lining and immune cells will engulf the HDL, creating plaque. She is at high risk of blood clots.", "LDL will get into damaged arterial lining and immune cells will engulf the LDL, creating plaque. She is at high risk of blood clots.", "High HDL means that cholesterol will be carried away from tissues and to the liver. She is at low risk of blood clots.", "Low LDL means that cholesterol will be carried away from tissues and to the liver. She is at low risk of blood clots."]', 2, null)
) as questions(order_index, prompt, choices, correct_index, image_url);
